// TestTTILobd_UnMarshalFrom_Fail exercises the defensive paths of UnMarshalFrom
// to ensure malformed or inconsistent payloads are rejected with an error.
func TestTTILobd_UnMarshalFrom_Fail(t *testing.T) {
	t.Parallel()
	testCases := []struct {
		name           string
		setupFunc      func(t *testing.T, msg *tTIlobd) (common.Marshaller, error)
		ctx            context.Context
		expectSetupErr bool
		wantCode       string
		wantErrMsg     string
	}{
		{
			name: "marshaller read failure",
			ctx:  context.Background(),
			setupFunc: func(t *testing.T, msg *tTIlobd) (common.Marshaller, error) {
				t.Helper()
				output := make(common.B1Array, 128)
				msg.setBuffer(output)

				payload := []byte{0x02, 0xDE, 0xAD}
				mar := createMarshaller(payload, failOnReadBytes, 1)
				return mar, nil
			},
			wantCode:   string(oracleErrors.FailUnmarshal),
			wantErrMsg: "can't unmarshal CLR",
		},
	}

	for _, tc := range testCases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			msg := newTTIlobd().(*tTIlobd)
			mar, err := tc.setupFunc(t, msg)
			if tc.expectSetupErr {
				if err == nil {
					t.Fatalf("expected setup error, got nil")
				}
				sqErr := requireSQLError(t, err)
				if code := sqErr.ErrorCode(); code != tc.wantCode {
					t.Fatalf("unexpected setup error code: got %s want %s", code, tc.wantCode)
				}
				if tc.wantErrMsg != "" && !strings.Contains(err.Error(), tc.wantErrMsg) {
					t.Fatalf("unexpected setup error message: %v", err)
				}
				return
			}

			if err != nil {
				t.Fatalf("setupFunc returned error: %v", err)
			}

			err = msg.UnMarshalFrom(tc.ctx, mar)
			if err == nil {
				t.Fatalf("expected error, got nil")
			}
			if tc.wantCode != "" {
				sqErr := requireSQLError(t, err)
				if code := sqErr.ErrorCode(); code != tc.wantCode {
					t.Fatalf("unexpected error code: got %s want %s", code, tc.wantCode)
				}
			}
		})
	}
}

