// TestTTILobd_MarshalTo_Success confirms that TTILOBD input buffers are marshalled
// into the correct byte representation for transmission to the server.
func TestTTILobd_MarshalTo_Success(t *testing.T) {
	t.Parallel()
	clobData := strings.Repeat("This is a large text example. ", 20)
	inputBuffer := encodeStringToUTF16BE(clobData)

	ctx := context.Background()
	dataBuffer := NewArrayDataBuffer(1205)
	engine := NewMarshalEngine(dataBuffer, common.BIG_ENDIAN, [5]byte{Native, Universal, Universal, Universal, Universal})

	msg := newTTIlobd().(*tTIlobd)
	msg.setBuffer(inputBuffer)

	if err := msg.MarshalTo(ctx, engine); err != nil {
		t.Fatalf("MarshalTo returned error: %v", err)
	}

	written := dataBuffer.bytes
	if len(written) == 0 {
		t.Fatal("MarshalTo did not write any bytes")
	}

	if len(written) <= 1 {
		t.Fatalf("expected CLR payload to follow message code, got %d bytes", len(written))
	}

	if !bytes.Equal(written, expectedPayload) {
		t.Fatalf("payload mismatch:\ngot  % X\nwant % X", written, expectedPayload)
	}
}

// TestTTILobd_MarshalTo_Fail ensures MarshalTo surfaces well-defined SQLErrors
// when presented with invalid buffers or data buffer failures.
func TestTTILobd_MarshalTo_Fail(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	testCases := []struct {
		name           string
		setupEngine    func() *MarshalEngine
		setupMsg       func(msg *tTIlobd) error
		expectSetupErr bool
		wantCode       string
		wantErrMsg     string
	}{
		{
			name: "lob payload marshal failure",
			setupEngine: func() *MarshalEngine {
				faulty := &FaultyArrayBasedDataBuffer{
					ArrayBasedDataBuffer: NewArrayDataBuffer(64),
					FailOnWriteBytesCall: 1,
				}
				return NewMarshalEngine(faulty, common.BIG_ENDIAN, [5]byte{Native, Universal, Universal, Universal, Universal})
			},
			setupMsg: func(msg *tTIlobd) error {
				payload := common.B1Array{0xAB, 0xCD, 0xEF}
				msg.setBuffer(payload)
				return nil
			},
			wantCode:   string(oracleErrors.FailMarshal),
			wantErrMsg: "CLR",
		},
	}

	for _, tc := range testCases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			msg := newTTIlobd().(*tTIlobd)
			engine := tc.setupEngine()
			err := tc.setupMsg(msg)

			if tc.expectSetupErr {
				if err == nil {
					t.Fatalf("expected setup error, got nil")
				}
				sqErr := requireSQLError(t, err)
				if code := sqErr.ErrorCode(); code != tc.wantCode {
					t.Fatalf("unexpected setup error code: got %s want %s", code, tc.wantCode)
				}
				if !strings.Contains(err.Error(), tc.wantErrMsg) {
					t.Fatalf("unexpected setup error message: %v", err)
				}
				return
			}

			if err != nil {
				t.Fatalf("setupMsg returned error: %v", err)
			}

			err = msg.MarshalTo(ctx, engine)
			if err == nil {
				t.Fatalf("expected error, got nil")
			}

			sqErr := requireSQLError(t, err)
			if code := sqErr.ErrorCode(); code != tc.wantCode {
				t.Fatalf("unexpected error code: got %s want %s", code, tc.wantCode)
			}
			if !strings.Contains(err.Error(), tc.wantErrMsg) {
				t.Fatalf("unexpected error message: %v", err)
			}
		})
	}
}

// requireSQLError converts a generic error into an oracleErrors.SQLError for assertions
// and fails the test immediately when the conversion is not possible.
func requireSQLError(t *testing.T, err error) oracleErrors.SQLError {
	t.Helper()
	sqErr, ok := err.(oracleErrors.SQLError)
	if !ok {
		t.Fatalf("expected oracleErrors.SQLError, got %T", err)
	}
	return sqErr
}

// normalizeLOBText decodes UTF-16 big-endian data from an output buffer and
// trims trailing null bytes to obtain a comparable string representation.
func normalizeLOBText(data common.B1Array) string {
	length := effectiveDataLength(data)
	if length == 0 {
		return ""
	}
	if length%2 != 0 {
		length--
	}
	words := make([]uint16, length/2)
	for i := 0; i < len(words); i++ {
		words[i] = binary.BigEndian.Uint16(data[i*2:])
	}
	decoded := string(utf16.Decode(words))
	return strings.Trim(decoded, "\x00")
}

// encodeStringToUTF16BE converts a Go string into a UTF-16 big-endian encoded
// byte slice to be used as a LOB payload for marshaling.
func encodeStringToUTF16BE(value string) common.B1Array {
	if value == "" {
		return common.B1Array{}
	}
	units := utf16.Encode([]rune(value))
	bytes := make(common.B1Array, len(units)*2)
	for i, unit := range units {
		binary.BigEndian.PutUint16(bytes[i*2:], unit)
	}
	return common.B1Array(bytes)
}

// effectiveDataLength returns the index of the last non-zero byte plus one,
// effectively trimming trailing zeros from the supplied buffer.
func effectiveDataLength(data common.B1Array) int {
	lastNonZero := -1
	for i, b := range data {
		if b != 0 {
			lastNonZero = i
		}
	}
	return lastNonZero + 1
}

